function sumSteps(steps) {
  let total = 0;
  for (const s of steps) total += s;
  return total;
}

function marginMs(totalMs, budgetMs) {
  return budgetMs - totalMs;
}

function withinBudget(totalMs, budgetMs) {
  return totalMs <= budgetMs;
}

function peakRate(average, ratio) {
  return average * ratio;
}

function inFlight(ratePerSec, seconds) {
  return ratePerSec * seconds;
}

function estimateLatency(step) {
  if (typeof step === "number") return step;
  if (step.sequential) {
    let total = 0;
    for (const s of step.sequential) total += estimateLatency(s);
    return total;
  }
  return Math.max(...step.parallel.map(estimateLatency));
}

function serversNeeded(peak, capacity, targetPercent) {
  return Math.ceil((peak * 100) / (capacity * targetPercent));
}

function loadedLatencyMs(nominalMs, utilizationPercent) {
  if (utilizationPercent >= 100) {
    throw new RangeError("utilization must be below 100");
  }
  return (nominalMs * 100) / (100 - utilizationPercent);
}

function maxUtilizationPercent(nominalMs, budgetMs) {
  if (nominalMs >= budgetMs) return 0;
  return (100 * (budgetMs - nominalMs)) / budgetMs;
}
